#include <stdio.h>

/* 极简模拟：三层 B+ 树，打印一次等值查找经过的节点（每层算一次磁盘 IO） */
static void find(int key) {
    printf("查找 key=%d 的路径:\n", key);
    /* 第 1 层：根节点（常驻内存，不计 IO） */
    int branch = key < 50 ? 0 : 1;
    printf("  L1 根节点  [10|50|90] -> 走子节点 %d（常驻内存，不计 IO）\n", branch);
    /* 第 2 层：内部节点（一次 IO 读一页，含多个 key） */
    int seg;
    if (key < 50) seg = key < 30 ? 0 : 1;
    else          seg = key < 70 ? 0 : 1;
    printf("  L2 内部节点 [%s] -> 定位到叶子    <-- 1 次磁盘 IO\n", key < 50 ? "10|20|30|40" : "50|60|70|80");
    /* 第 3 层：叶子节点（存真实数据，一次 IO） */
    printf("  L3 叶子节点 [%s] -> 命中数据行   <-- 1 次磁盘 IO\n",
           key < 50 ? "10,20,30,40" : "50,60,70,80");
    printf("  合计磁盘 IO 次数 = 2（对比二叉树的 ~30 次）\n");
}

int main(void) {
    printf("B+ 树要点：内部节点只存 key+指针（不放数据）-> 一页能塞更多 key -> 树更矮\n");
    find(35);
    printf("\n");
    find(65);
    printf("\n叶子之间有链表 -> 范围查询 WHERE k BETWEEN 35 AND 65 只需顺序扫描叶子\n");
    return 0;
}
